<include file="Public:header"/>	<form id="myform" method="post" action="{pigcms{:U('course_edit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="course_id" value="{pigcms{$detail.course_id}" />		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">				<tr>				<th width="15%">标题</th>                <td>	                <input type="text" class="input fl" name="title" id="title" value="{pigcms{$detail['title']}">                </td>			</tr>			<tr>				<th width="15%">分类</th>                <td>                	 <select  name="cat_id" class="select">                        <volist name="category" id="vo">                        	<option value="{pigcms{$vo.id}" <if condition="$vo['id'] eq $detail['cat_id']">selected</if>>{pigcms{$vo.name}</option>                        </volist>                    </select>                </td>			</tr>			<tr>				<th width="15%">详情描写</th>                <td>	                <textarea name="content" style="width: 300px;height: 200px">{pigcms{$detail['content']}</textarea>                </td>			</tr>			<tr>				<th width="15%">封面图片</th>                <td>                	<a href="javascript:void(0)" class="btn btn-sm btn-success J_selectImage" style="background: #87b87f!important;border-color: #87b87f;color:#fff;" >上传图片</a>&nbsp;&nbsp;推荐尺寸8:5	                <input type="hidden" class="input-image" name="cover_img" id="pic_list" value="{pigcms{$detail['cover_img']}">	                <ul class="image_product_list" id="avatar_detail">	                </ul>	                <ul class="avatar_list" id="avatar_show" >		                <if condition="$detail.cover_img neq ''">		                    <li  class="upload_pic_li1" style="float:left;list-style:none;"><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('view_image',array('url'=>urlencode(file_domain().$detail['cover_img'])))}','查看大图',700,600,true,false,false,'','',true);"><img src="{pigcms{:file_domain().$detail['cover_img']}" style="width:200px;height:125px;margin-right:5px;"></a></li>		                   		                </if>	                </ul>                </td>			</tr>							</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form>	<link rel="stylesheet" href="{pigcms{$static_public}kindeditor/themes/default/default.css">	<script src="{pigcms{$static_public}kindeditor/kindeditor.js"></script>	<script src="{pigcms{$static_public}kindeditor/lang/zh_CN.js"></script>	<script type="text/javascript">		KindEditor.ready(function(K){			var editor = K.editor({				allowFileManager : true			});            $('.J_selectImage').click(function(){                var upload_file_btn = $(this);                editor.uploadJson = "{pigcms{:U('Config/ajax_upload_pic')}&type=recruit";                editor.loadPlugin('image', function(){                    editor.plugin.imageDialog({                        showRemote : false,                        clickFn : function(url, title, width, height, border, align) {                            var avatar_detail_length = $('#avatar_detail').find('li').length;                            var li_length = upload_file_btn.siblings('.avatar_list').find('li').length+avatar_detail_length;                                $('#avatar_show').show();                                                              upload_file_btn.siblings('.input-image').val(url);                                                                var html='<li class="upload_pic_li" style="float:left;list-style:none;"><img src="'+url+'" style="width:90px;height:50px;margin-right:5px;"><br></li>';                                upload_file_btn.siblings('.avatar_list').html(html)                                editor.hideDialog();                                                        }                    });                });            });        })			</script>	<include file="Public:footer"/>